/**
 * Home hero (slot homeSlots.heroEcg): a live normal 12-lead — generated by src/synth from one cardiac source, drawn by
 * src/ecg at 25 mm/s and 10 mm/mV. Read first, then reveal: the measurements and the wave labels stay hidden until the
 * learner asks for them (the prompt asks them to find P, QRS and T in lead II); "another normal ECG" draws a new seeded
 * normal so the learner sees how much a normal tracing can vary. The whole sheet always fits the card (the paper height
 * follows the card width, hero.ts heroPaperHeight), so no lead is cut off and nothing scrolls sideways — also on
 * phones, which get a 6×2 sheet. Layout-stable: the box keeps its size while generating and between examples, and the
 * line under it reserves its lines; only "label the waves" (asked for) makes the paper taller.
 * Falls back to the paper explainer if the engine fails.
 */
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'preact/hooks';
import type { Ecg } from '../core/ecg';
import { EcgView } from '../ecg';
import { tsh } from '../i18n/shell';
import { generate } from '../synth';
import { Button, Icon } from '../ui';
import { heroDay, heroFacts, heroPaperHeight, heroRequest, signedDeg, type HeroLayout } from './hero';
import { PaperExplainer } from './PaperExplainer';
import { href } from './router';
import './pages.css';

/** Phones get the 6×2 sheet (5 s per lead, larger rows); wider screens the 3×4 + lead II rhythm strip. */
const NARROW_QUERY = '(max-width: 560px)';
/** Paper height until the card has been measured. */
const DEFAULT_H = 200;

/** Is the viewport phone-narrow (follows rotation / resizing). */
function useNarrow(): boolean {
  const mq = useMemo(() => globalThis.matchMedia?.(NARROW_QUERY) ?? null, []);
  const [narrow, setNarrow] = useState(() => !!mq?.matches);
  useEffect(() => {
    if (!mq) return;
    const on = () => setNarrow(mq.matches);
    mq.addEventListener('change', on);
    return () => mq.removeEventListener('change', on);
  }, [mq]);
  return narrow;
}

/** Content width of an element in CSS px (0 until measured), following resizes. */
function useWidth(ref: { readonly current: HTMLElement | null }): number {
  const [w, setW] = useState(0);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    setW(el.clientWidth);
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver((entries) => {
      const cw = entries[0]?.contentRect.width;
      if (cw !== undefined) setW(Math.floor(cw));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return w;
}

type State = { readonly n: number; readonly ecg: Ecg } | { readonly n: number; readonly ecg: null; readonly failed: boolean };

export function HeroEcg() {
  const day = useMemo(() => heroDay(new Date()), []);
  const [n, setN] = useState(0);
  const [labels, setLabels] = useState(false);
  const [state, setState] = useState<State>({ n: -1, ecg: null, failed: false });
  const layout: HeroLayout = useNarrow() ? '6x2' : '3x4+1';
  const paperRef = useRef<HTMLDivElement>(null);
  const width = useWidth(paperRef);
  const height = width > 0 ? heroPaperHeight(width, layout, labels && !!state.ecg) : DEFAULT_H;

  // generate after the first paint (the page is usable at once); a new example replaces the old one when it is ready
  useEffect(() => {
    let live = true;
    const id = setTimeout(() => {
      let next: State;
      try {
        next = { n, ecg: generate(heroRequest(day, n)).ecg };
      } catch {
        next = { n, ecg: null, failed: true };
      }
      if (live) setState(next);
    }, 0);
    return () => {
      live = false;
      clearTimeout(id);
    };
  }, [day, n]);

  if (state.ecg === null && state.failed) return <PaperExplainer />;

  const ecg = state.ecg;
  const truth = ecg?.truth ?? null;
  const f = truth ? heroFacts(truth) : null;
  const busy = state.n !== n;

  return (
    <figure class="home-ecg" aria-busy={busy}>
      <figcaption class="home-ecg__head">
        <strong>{tsh('heroTitle')}</strong>
        <span class="app-muted tabular">{tsh('heroSub')}</span>
      </figcaption>
      <div class="home-ecg__paper" ref={paperRef}>
        {ecg ? (
          <EcgView
            ecg={ecg}
            layout={layout}
            lead="II"
            speed={25}
            gain={10}
            chestHalfGain={false}
            cabrera={false}
            height={height}
            toolbar={false}
            tools={false}
            overlays={labels ? { waveLabels: true, intervals: true } : undefined}
            ariaLabel={tsh('heroAria')}
          />
        ) : (
          <div class="home-ecg__wait" role="status" style={{ height: `${height}px` }}>
            <Icon name="wave" size={22} />
            <span>{tsh('heroGenerating')}</span>
          </div>
        )}
      </div>
      <p class="home-ecg__facts tabular" aria-live="polite">
        {labels && f
          ? tsh('heroFacts', {
              rate: f.rateBpm,
              pr: f.prMs ?? '—',
              qrs: f.qrsMs,
              qt: f.qtMs,
              qtc: f.qtcMs,
              axis: signedDeg(f.axisDeg),
            })
          : tsh('heroPrompt')}
      </p>
      <div class="home-ecg__actions">
        <Button size="sm" icon="eye" aria-pressed={labels} disabled={!ecg} onClick={() => setLabels(!labels)}>
          {labels ? tsh('heroHide') : tsh('heroShow')}
        </Button>
        <Button size="sm" icon="refresh" disabled={busy} onClick={() => setN(n + 1)}>
          {tsh('heroNew')}
        </Button>
        <a class="home-ecg__why" href={href({ name: 'finding', id: 'normal-ecg' })}>
          {tsh('heroWhy')}
          <Icon name="next" size={16} />
        </a>
      </div>
    </figure>
  );
}
